import { Component } from '@angular/core';
import { ProdavnicaService } from '../prodavnica.service';
import jwt_decode from 'jwt-decode'; // Uvezi jwt-decode
import { ArtikalService } from '../artikal.service';


@Component({
  selector: 'app-dodavanje-artikla',
  templateUrl: './dodavanje-artikla.component.html',
  styleUrls: ['./dodavanje-artikla.component.css']
})
export class DodavanjeArtiklaComponent {
  artikli: any[] = [];
  email: string = '';
  errors: string[] = []; // Niz za poruke o grešci
  successMessage: string | null = null; // Poruka o uspehu

  constructor(private prodavnicaService: ProdavnicaService, private artikalService: ArtikalService) {}

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.email = decodedToken.email;
    }
  }

  removeArtikal(index: number): void {
    this.artikli.splice(index, 1); // Uklanja artikal iz liste
    this.errors.splice(index, 1); // Takođe uklanja eventualne greške vezane za artikal
  }

  // Funkcija za rukovanje promenom fajla
  onFileChange(event: any) {
    const files = event.target.files;


    this.artikli = [];
    this.errors = []; // Resetujemo greške
    for (let file of files) {
      const reader = new FileReader();
      reader.onload = (e: any) => {
        this.artikli.push({
          file: file,
          preview: e.target.result,
          tip: '',
          kategorija: '',
          velicina: '',
          boja: '',
          cena: ''
        });
        this.errors.push(''); // Prazna greška za svaki artikal
      };
      reader.readAsDataURL(file);
    }
  }

  // Funkcija za proveru validnosti svakog unosa
  validateField(artikal: any, index: number) {
    if (!artikal.tip || !artikal.kategorija || !artikal.velicina || !artikal.boja || !artikal.cena) {
      this.errors[index] = 'Sva polja moraju biti popunjena!';
    } else {
      this.errors[index] = ''; // Ukloni grešku ako su polja validna
    }
  }

  // Funkcija za validaciju i slanje
  onSubmit() {
    let hasErrors = false;
    let savedCount = 0; // Broji uspešno sačuvane artikle

    // Validacija svakog artikla
    this.artikli.forEach((artikal, index) => {
      if (!artikal.tip || !artikal.kategorija || !artikal.velicina || !artikal.boja || !artikal.cena) {
        this.errors[index] = 'Sva polja moraju biti popunjena!';
        hasErrors = true;
      } else {
        this.errors[index] = ''; // Ako je sve popunjeno, nema greške
      }
    });

    if (hasErrors) {
      return; // Ako postoje greške, zaustavi proces
    }

    // Ako nema grešaka, sačuvaj artikle
    this.artikli.forEach((artikal, index) => {
      const formData = new FormData();
      formData.append('image', artikal.file);
      formData.append('tip', artikal.tip);
      formData.append('kategorija', artikal.kategorija);
      formData.append('velicina', artikal.velicina);
      formData.append('boja', artikal.boja);
      formData.append('cena', artikal.cena);
      formData.append('email', this.email);

      this.artikalService.saveArtikal(formData).subscribe(
        (response) => {
          savedCount++;
          if (savedCount === this.artikli.length) {
            // Svi artikli uspešno sačuvani
            this.successMessage = 'Svi artikli su uspešno sačuvani!';
            this.artikli = []; // Resetuj formu
            setTimeout(() => this.successMessage = null, 5000); // Poruka nestaje nakon 5 sekundi
          }
        },
        (error) => {
          console.error(`Greška pri čuvanju artikla ${index + 1}.`);
        }
      );
    });
  }
}
<div class="form-container">
  <h1>Dodajte Artikal</h1>

  <!-- Poruka o uspešnom dodavanju -->
  <div *ngIf="successMessage" class="success-message">
    {{ successMessage }}
  </div>

  <div class="form-group">
    <label for="images">Izaberite slike:</label>
    <div class="custom-file-upload">
      <input type="file" id="images" (change)="onFileChange($event)" accept="image/*" multiple />
    </div>
  </div>

  <div *ngIf="artikli.length > 0" class="artikli-container">
    <div *ngFor="let artikal of artikli; let i = index" class="artikal-form">
      <span class="remove-icon" (click)="removeArtikal(i)">✖</span> <!-- Ikona za brisanje -->
      <img [src]="artikal.preview" alt="Artikal slika" class="artikal-image" />
      <div class="artikal-details">
        <label for="tip">Tip:</label>
        <select id="tip" [(ngModel)]="artikal.tip" (change)="validateField(artikal, i)">
          <option value="majica">Majica</option>
          <option value="haljina">Haljina</option>
          <option value="farmerice">Farmerice</option>
          <option value="jakna">Jakna</option>
          <option value="duks">Duks</option>
          <option value="suknja">Suknja</option>
          <option value="kaput">Kaput</option>
          <option value="kosulja">Košulja</option>
          <option value="sorts">Šorts</option>
          <option value="trenirka">Trenerka</option>
          <option value="bluza">Bluza</option>
        </select>
        <div *ngIf="!artikal.tip && errors[i]" class="error">Tip je obavezan</div>

        <label for="kategorija">Kategorija:</label>
        <select id="kategorija" [(ngModel)]="artikal.kategorija" (change)="validateField(artikal, i)">
          <option value="muski">Muški</option>
          <option value="zenski">Ženski</option>
          <option value="unisex">Unisex</option>
        </select>
        <div *ngIf="!artikal.kategorija && errors[i]" class="error">Kategorija je obavezna</div>

        <label for="velicina">Veličina:</label>
        <select id="velicina" [(ngModel)]="artikal.velicina" (change)="validateField(artikal, i)">
          <option value="XS">XS</option>
          <option value="S">S</option>
          <option value="M">M</option>
          <option value="L">L</option>
          <option value="XL">XL</option>
          <option value="XXL">XXL</option>
          <option value="XXXL">XXXL</option>
          <option value="Jedna veličina">Jedna veličina</option>
        </select>
        <div *ngIf="!artikal.velicina && errors[i]" class="error">Veličina je obavezna</div>

        <label for="boja">Boja:</label>
        <select id="boja" [(ngModel)]="artikal.boja" (change)="validateField(artikal, i)">
          <option value="bela">Bela</option>
          <option value="crna">Crna</option>
          <option value="roze">Roze</option>

          <option value="crvena">Crvena</option>
          <option value="plava">Plava</option>
          <option value="zelena">Zelena</option>
          <option value="žuta">Žuta</option>
          <option value="siva">Siva</option>
          <option value="narandžasta">Narandžasta</option>
          <option value="ljubičasta">Ljubičasta</option>
          <option value="braon">Braon</option>
        </select>
        <div *ngIf="!artikal.boja && errors[i]" class="error">Boja je obavezna</div>

        <label for="cena">Cena:</label>
        <input type="number" id="cena" [(ngModel)]="artikal.cena" placeholder="Unesite cenu u dinarima" (input)="validateField(artikal, i)" />
        <div *ngIf="!artikal.cena && errors[i]" class="error">Cena je obavezna</div>
      </div>
    </div>
  </div>

  <button (click)="onSubmit()" [disabled]="artikli.length === 0">Sačuvaj artikle</button>
</div>
